import{_ as e,o,c as n,ah as i}from"./chunks/framework.C-FRNfAJ.js";const d=JSON.parse(`{"title":"L'Éclosion","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/activites/eclosion.md","filePath":"src/en/guide/activites/eclosion.md"}`),s={name:"en/guide/activites/eclosion.md"};function r(a,t,c,l,p,g){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="l-eclosion" tabindex="-1">L&#39;Éclosion <a class="header-anchor" href="#l-eclosion" aria-label="Permalink to &quot;L&#39;Éclosion&quot;">​</a></h1><p>L&#39;Éclosion is NextBoxx&#39;s incubation program. It is open to former <strong>Canopé</strong> learners, to <strong>external project holders</strong> and to <strong>contest laureates</strong>. It runs in <strong>cycles</strong>, with an application deadline.</p><h2 id="applying" tabindex="-1">Applying <a class="header-anchor" href="#applying" aria-label="Permalink to &quot;Applying&quot;">​</a></h2><p>Any account can apply from <strong>Activities → My L&#39;Éclosion project</strong>, <strong>once per cycle</strong>, as long as submissions are open (the page shows the closing date). If no cycle is open, the page says so.</p><p>Fill in:</p><ul><li>the <strong>project name</strong> and its <strong>sector</strong>;</li><li>the <strong>problem</strong> it addresses and the <strong>solution</strong> proposed;</li><li>the <strong>progress</strong>: prototype, first customers, team, figures;</li><li>a <strong>pitch</strong> as a PDF, optional (5 MB at most).</li></ul><p>The application&#39;s <strong>origin</strong> is kept: the &quot;Canopé&quot; route is only offered to an account in the Canopé status; others apply as external project holders. <strong>Contest laureates</strong> are entered for their account by the Incubation Officer.</p><p>The Incubation Officer examines your application and informs you of their decision. If your project is <strong>retained</strong>, you become a <strong>Project holder</strong> and a NextBoxx participation may be proposed to you. You follow the application, the decision and the validated participation on the same page. If the project is refused, you receive the reason.</p><h2 id="running-the-cycles-incubation-officer" tabindex="-1">Running the cycles (Incubation Officer) <a class="header-anchor" href="#running-the-cycles-incubation-officer" aria-label="Permalink to &quot;Running the cycles (Incubation Officer)&quot;">​</a></h2><p>The Incubation Officer manages <strong>Activities → L&#39;Éclosion</strong>.</p><ol><li><strong>New cycle</strong>: title, <strong>submission deadline</strong>, <strong>start</strong> and <strong>end</strong> of incubation. Submissions close at the latest at the start of incubation. The cycle is created as a <strong>draft</strong>: nobody can apply yet.</li><li><strong>Open to applications</strong>: accounts can apply until the deadline.</li><li><strong>Enter a laureate</strong>: find the account by its e-mail address, with the contest&#39;s name and year. This is possible until the end of incubation.</li><li><strong>Examine</strong> each application, with its documents: <strong>Retain the project</strong>, or <strong>Refuse</strong> with a reason. Only the Incubation Officer decides.</li></ol><h2 id="the-participation-and-the-investment-committee" tabindex="-1">The participation and the investment committee <a class="header-anchor" href="#the-participation-and-the-investment-committee" aria-label="Permalink to &quot;The participation and the investment committee&quot;">​</a></h2><p>For a retained project with no participation in progress, the Officer <strong>proposes a participation</strong>: the <strong>type</strong> (equity stake, or revenue share), the <strong>percentage</strong> and the <strong>terms</strong> (duration, exit clause, counterparts). <strong>Submit to the committee</strong> places it &quot;With the committee&quot;.</p><p>The <strong>investment committee</strong> has three seats: the <strong>Incubation Officer</strong>, the <strong>Pedagogical Coordinator</strong> and the <strong>Direction</strong>. It decides <strong>unanimously</strong>:</p><ul><li>the proposal counts as the Officer&#39;s <strong>vote for</strong>;</li><li>the Coordinator and the Direction then vote, <strong>each from a different account</strong> (one person does not sit twice on the same participation);</li><li>a <strong>vote against</strong>, with its reason, <strong>refuses</strong> the participation; the Officer receives the reason and can propose a new one.</li></ul><p>Members vote from <strong>Activities → Investment committee</strong>, which lists participations <strong>To vote</strong> and recent decisions. A participation is <strong>only activated once validated</strong> by all three votes. The Direction sees the portfolio of validated participations.</p>',16)])])}const u=e(s,[["render",r]]);export{d as __pageData,u as default};
